UPDATE public.emenda_beneficiarios b SET
  nome = v.nome,
  entrega_municipio = v.municipio,
  entrega_uf = v.uf,
  entrega_bairro = COALESCE(b.entrega_bairro, v.bairro),
  outros_nomes = CASE WHEN v.antes = ANY(b.outros_nomes) THEN b.outros_nomes ELSE array_append(b.outros_nomes, v.antes) END,
  versao = b.versao + 1,
  atualizado_por = NULL,
  atualizado_por_nome = 'Limpeza dos nomes (migration 167)',
  atualizado_em = NOW()
FROM v
WHERE b.id = v.id
  AND b.nome = v.antes
  AND b.entrega_municipio IS NOT DISTINCT FROM v.municipio_antes
  AND b.entrega_uf IS NOT DISTINCT FROM v.uf_antes;
